package de.example.reports.listener;
import de.example.reports.database.Database; import de.example.reports.gui.*; import de.example.reports.moderation.ModerationService; import io.papermc.paper.event.player.AsyncChatEvent; import org.bukkit.entity.Player; import org.bukkit.event.*; import org.bukkit.event.inventory.*; import org.bukkit.event.player.*; import org.bukkit.plugin.java.JavaPlugin;
public final class ReportListener implements Listener { private final Database db;private final ReportGuiService gui;private final AdminReportGuiService adminGui;private final ModerationService moderation;private final SignInput sign; public ReportListener(JavaPlugin p,Database d,ReportGuiService g,AdminReportGuiService a,ModerationService m,SignInput s){db=d;gui=g;adminGui=a;moderation=m;sign=s;p.getServer().getPluginManager().registerEvents(this,p);} @EventHandler public void join(PlayerJoinEvent e){db.upsertPlayer(e.getPlayer().getUniqueId(),e.getPlayer().getName());moderation.check(e.getPlayer());} @EventHandler public void quit(PlayerQuitEvent e){sign.clear(e.getPlayer().getUniqueId());}
 @EventHandler(ignoreCancelled=true) public void chat(AsyncChatEvent e){if(moderation.muted(e.getPlayer())){e.setCancelled(true);e.getPlayer().sendMessage("§cDu bist stummgeschaltet.");}}
 @EventHandler(ignoreCancelled=true) public void click(InventoryClickEvent e){Object holder=e.getView().getTopInventory().getHolder(false);if(!(holder instanceof ReportInventory)&&!(holder instanceof AdminReportInventory))return;e.setCancelled(true);if(!(e.getWhoClicked() instanceof Player p))return;if(e.getClickedInventory()==null||e.getClickedInventory()!=e.getView().getTopInventory())return;if(e.getClick().isKeyboardClick()||e.getClick().isShiftClick()||e.getClick()==ClickType.DOUBLE_CLICK)return;if(holder instanceof ReportInventory reportHolder){if(e.getSlot()==53){gui.search(p,reportHolder);return;}gui.click(p,reportHolder,e.getSlot());}else adminGui.click(p,(AdminReportInventory)holder,e.getSlot(),e.isRightClick());}
 @EventHandler(ignoreCancelled=true) public void drag(InventoryDragEvent e){Object holder=e.getView().getTopInventory().getHolder(false);if(holder instanceof ReportInventory||holder instanceof AdminReportInventory)e.setCancelled(true);} @EventHandler(ignoreCancelled=true) public void move(InventoryMoveItemEvent e){Object source=e.getSource().getHolder(false),destination=e.getDestination().getHolder(false);if(source instanceof ReportInventory||source instanceof AdminReportInventory||destination instanceof ReportInventory||destination instanceof AdminReportInventory)e.setCancelled(true);}
}
